  Ciphertext q = square(t2);
  Ciphertext a = t2 * c6;
  Ciphertext e = a + a + c4;
  Ciphertext f = e + e;
  Ciphertext p = f * q - e;
  Ciphertext u = t2 * c2;
  Ciphertext w = z * c1;
  Ciphertext lower = u - a;
  Ciphertext result = p + lower;
  result = result + w;
  result = result + c0;
  result.set_output("y");
}
```

